package pe.edu.upeu.inscripcion.controller;
import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import pe.edu.upeu.inscripcion.dto.*;import pe.edu.upeu.inscripcion.service.*;import pe.edu.upeu.inscripcion.repository.InscripcionRepository;import pe.edu.upeu.inscripcion.client.CertificadoContextoClient;import java.util.*;
@RestController @RequestMapping("/api/v1/inscripciones") @RequiredArgsConstructor
public class InscripcionController {
 private final InscripcionService service;private final CertificadoPdfService pdfService;private final CertificadoDocumentoService documentos;private final CertificadoContextoClient acceso;private final InscripcionRepository repo;
 private void propietario(Long id,String auth){acceso.propietario(repo.estudianteDe(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)),auth);}
 @GetMapping public List<InscripcionResponse> listar(@RequestHeader(name="Authorization",required=false)String a){acceso.admin(a);return service.listar();}
 @GetMapping("/{id}") public InscripcionResponse obtener(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.obtener(id);}
 @GetMapping("/estudiante/{id}") public List<InscripcionResponse> estudiante(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){acceso.propietario(id,a);return service.porEstudiante(id);}
 @GetMapping("/curso/{id}") public List<InscripcionResponse> curso(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){acceso.docenteCurso(id,a);return service.porCurso(id);}
 @PostMapping public ResponseEntity<InscripcionResponse> crear(@Valid @RequestBody InscripcionRequest r,@RequestHeader(name="Authorization",required=false)String a){acceso.propietario(r.estudianteId(),a);return ResponseEntity.status(201).body(service.crear(r));}
 @PutMapping("/{id}/estado") public InscripcionResponse estado(@PathVariable Long id,@Valid @RequestBody EstadoRequest r,@RequestHeader(name="Authorization",required=false)String a){acceso.admin(a);return service.cambiarEstado(id,r);}
 @PutMapping("/{id}/lecciones/{leccionId}/completar") public InscripcionResponse completar(@PathVariable Long id,@PathVariable Long leccionId,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.completarLeccion(id,leccionId);}
 @PostMapping("/{id}/asistencias") public AsistenciaResponse asistencia(@PathVariable Long id,@Valid @RequestBody AsistenciaRequest r,@RequestHeader(name="Authorization",required=false)String a){acceso.docenteCurso(repo.cursoDe(id).orElseThrow(),a);return service.registrarAsistencia(id,r);}
 @GetMapping("/{id}/asistencias") public List<AsistenciaResponse> asistencias(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.asistencias(id);}
 @GetMapping("/{id}/estado-academico") public EstadoAcademicoResponse academico(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.estadoAcademico(id);}
 @PostMapping("/{id}/certificado") public CertificadoResponse solicitar(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.solicitarCertificado(id);}
 @GetMapping("/{id}/certificado") public CertificadoResponse certificado(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){propietario(id,a);return service.certificado(id);}
 @PutMapping("/{id}/certificado/confirmar-pago") public CertificadoResponse confirmarPago(@PathVariable Long id){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"La confirmación solo se acepta del servicio de pagos");}
 @GetMapping(value="/{id}/certificado/pdf",produces="application/pdf") public ResponseEntity<byte[]> pdf(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){var d=documentos.documento(id,a);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+d.codigo()+".pdf").header("Cache-Control","private, no-store").contentType(MediaType.APPLICATION_PDF).body(pdfService.generar(d));}
 @GetMapping(value="/{id}/certificado/png",produces="image/png") public ResponseEntity<byte[]> png(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){var d=documentos.documento(id,a);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename="+d.codigo()+".png").header("Cache-Control","private, no-store").contentType(MediaType.IMAGE_PNG).body(pdfService.png(pdfService.generar(d)));}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void eliminar(@PathVariable Long id,@RequestHeader(name="Authorization",required=false)String a){acceso.admin(a);service.eliminar(id);}
}
